package com.bd2toolsbox.data.repository

/**
 * GameKee 原版阵容组件内嵌图标资源与样式（从官方前端 bundle 提取的原始 base64 / CDN 资源）。
 */
internal object GamekeeBattleAssets {
    const val ATTR_FIRE = "data:image/png;base64,"
    const val ATTR_WATER = "data:image/png;base64,"
    const val ATTR_WIND = "data:image/png;base64,"
    const val ATTR_LIGHT = "data:image/png;base64,"
    const val ATTR_DARK = "data:image/png;base64,"
    const val DMG_PHYS = "data:image/png;base64,"
    const val DMG_MAGIC = "data:image/png;base64,"
    const val BOSS_MAX_DMG = "data:image/png;base64,"
    const val BOSS_ARRANGED = "data:image/png;base64,"
    const val BOSS_UNARRANGED = "data:image/png;base64,"
    const val BOSS_GENERAL = "https://cdnstatic.gamekee.com/wiki/spa/apps/web/client/dist/assets/images/kadai-icon.e7be86b8.png"
    const val STRENTH_0 = "data:image/webp;base64,"
    const val STRENTH_1 = "data:image/webp;base64,"
    const val STRENTH_2 = "data:image/webp;base64,"
    const val STRENTH_3 = "data:image/webp;base64,"
    const val STRENTH_4 = "data:image/webp;base64,"
    const val STRENTH_5 = "data:image/webp;base64,"
    const val STRENTH_MAX = "data:image/webp;base64,"
    const val POT_34_0 = "data:image/png;base64,"
    const val POT_34_1 = "data:image/png;base64,"
    const val POT_5_0 = "data:image/png;base64,"
    const val POT_5_1 = "data:image/png;base64,"
    const val POT_5_2 = "data:image/png;base64,"
    const val POT_5_3 = "data:image/png;base64,"
    const val BURST_1 = "data:image/svg+xml;base64,"
    const val BURST_2 = "data:image/svg+xml;base64,"
    const val BURST_3 = "data:image/svg+xml;base64,"
    const val ORDER_1 = "data:image/png;base64,"
    const val ORDER_2 = "data:image/png;base64,"
    const val ORDER_3 = "data:image/png;base64,"
    const val ORDER_4 = "data:image/png;base64,"
    const val ORDER_5 = "https://cdnstatic.gamekee.com/wiki/spa/apps/web/client/dist/assets/images/skill-icon-5.8455e936.png"
    const val LANCELOT_ACTIVE = "data:image/webp;base64,"
    const val LANCELOT_STANDBY = "data:image/webp;base64,"
    const val EMPTY_SLOT_BG = "data:image/png;base64,"
    const val STAR_DEFAULT = "data:image/png;base64,"
    const val STAR_BURST = "data:image/png;base64,"

    fun attrIcon(attr: String): String = when {
        attr.contains("火") -> ATTR_FIRE
        attr.contains("水") -> ATTR_WATER
        attr.contains("风") -> ATTR_WIND
        attr.contains("光") -> ATTR_LIGHT
        attr.contains("暗") -> ATTR_DARK
        else -> ""
    }

    fun attrBgClass(attr: String): String = when {
        attr.contains("火") -> "zs-red"
        attr.contains("水") -> "zs-blue"
        attr.contains("风") -> "zs-green"
        attr.contains("光") -> "zs-yellow"
        attr.contains("暗") -> "zs-purple"
        else -> ""
    }

    fun damageIcon(damage: String): String = when {
        damage.contains("物理") -> DMG_PHYS
        damage.contains("魔法") -> DMG_MAGIC
        else -> ""
    }

    fun skillLvBadge(level: Int?): String = when (level) {
        1 -> ORDER_1
        2 -> ORDER_2
        3 -> ORDER_3
        4 -> ORDER_4
        5 -> ORDER_5
        else -> ""
    }

    fun strenthBadge(level: Int?): String = when (level) {
        0 -> STRENTH_0
        1 -> STRENTH_1
        2 -> STRENTH_2
        3 -> STRENTH_3
        4 -> STRENTH_4
        5 -> STRENTH_5
        else -> ""
    }

    fun potentialCornerBadge(star: Int, potential: Int): String {
        val p = potential.coerceIn(0, 3)
        return if (star in 1..4) {
            if (p >= 1) POT_34_1 else POT_34_0
        } else {
            when (p) {
                1 -> POT_5_1
                2 -> POT_5_2
                3 -> POT_5_3
                else -> POT_5_0
            }
        }
    }

    fun burstBadge(burst: Int?): String = when (burst) {
        1 -> BURST_1
        2 -> BURST_2
        3 -> BURST_3
        else -> ""
    }
}
